import { writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));

const colorsPath = join(__dirname, "../src/utils/colors.js");
const outputPath = join(__dirname, "../src/utils/colors.generated.css");

function buildTheme(colorsConfig) {
  let theme =
    "/* Auto-generated by vite-plugin-tailwind-colors — do not edit */\n@theme {\n";
  for (const [name, scale] of Object.entries(colorsConfig)) {
    if (scale && typeof scale === "object") {
      for (const [shade, value] of Object.entries(scale)) {
        theme += `  --color-${name}-${shade}: ${value};\n`;
      }
    } else if (typeof scale === "string" && scale.startsWith("#")) {
      theme += `  --color-${name}: ${scale};\n`;
    }
  }
  theme += "}\n";
  return theme;
}

async function generate() {
  const { default: colorsConfig } = await import(
    `${colorsPath}?t=${Date.now()}`
  );
  writeFileSync(outputPath, buildTheme(colorsConfig));
}

// Reads src/utils/colors.js and writes src/utils/colors.generated.css,
// a @theme block that Tailwind v4 picks up as CSS custom properties.
// Writing to disk (rather than injecting via transform) ensures that
// @reference directives in Vue <style> blocks also resolve the theme.
export default function tailwindColorsPlugin() {
  return {
    name: "vite-plugin-tailwind-colors",
    async buildStart() {
      await generate();
    },
    async handleHotUpdate({ file }) {
      if (file === colorsPath) await generate();
    },
  };
}
